// eslint-disable-next-line @typescript-eslint/require-await
const run = async (inputs) => {
    lib_core.info(`title is: ${inputs.title}`);
    // GitHub workspace directory.
    const gitHubWorkspaceDir = process.env.GITHUB_WORKSPACE; // || '/github/workspace'
    // Inputs.
    const markdownFiles = inputs.markdownFiles; // Required parameter.
    const title = inputs.title; // Required parameter.
    const author = inputs.author; // Required parameter.
    const publisher = inputs.publisher || undefined;
    const version = parseInt(inputs.version) || 3;
    const lang = inputs.lang || 'en';
    const tocTitle = inputs.tocTitle || undefined;
    const hideToC = inputs.hideToC === 'true';
    const output = inputs.output || 'book.epub';
    let cover = inputs.cover;
    if (!markdownFiles) {
        console.error('Missing required input: \'markdownFiles\'');
        process.exit(1);
    }
    if (!title) {
        console.error('Missing required input: \'title\'');
        process.exit(1);
    }
    if (!author) {
        console.error('Missing required input: \'author\'');
        process.exit(1);
    }
    // Check if the cover is a URL or a file path.
    if (typeof cover === 'string' && !cover.trim().startsWith('http')) {
        cover = `${gitHubWorkspaceDir}/${cover}`;
    }
    const includes = markdownFiles?.split('\n') || [];
    const chapters = [];
    for (const includeIndex in includes) {
        const regex = includes[includeIndex];
        const markdownFileNames = await glob(`${gitHubWorkspaceDir}/**/${regex.trim()}`, { ignore: 'node_modules/**' });
        // Sort the markdown files by name.
        if (markdownFileNames.length > 0) {
            markdownFileNames.sort();
        }
        for (const fileIndex in markdownFileNames) {
            const markdownFileName = markdownFileNames[fileIndex];
            // Read the markdown file to get the content of the file.
            const markdown = external_fs_default().readFileSync(external_path_default().resolve(import.meta.dirname, markdownFileName)).toString().trim();
            // Extract chapter title from markdown metadata.
            const chapterTitleMatch = markdown.match(/\[metadata:title\]:- "([^"]+)"/i);
            const chapterTitle = chapterTitleMatch ? chapterTitleMatch[1].trim() : undefined;
            // Extract chapter author from markdown metadata.
            const chapterAuthorMatch = markdown.match(/\[metadata:author\]:- "([^"]+)"/i);
            const chapterAuthor = chapterAuthorMatch ? chapterAuthorMatch[1].trim() : undefined;
            // Extract chapter excludeFromToc from markdown metadata.
            const chapterExcludeFromTocMatch = markdown.match(/\[metadata:excludeFromToc\]:- "([^"]+)"/i);
            const chapterExcludeFromToc = chapterExcludeFromTocMatch
                ? chapterExcludeFromTocMatch[1].trim() === 'true'
                : undefined;
            // Extract chapter excludeFromToc from markdown metadata.
            const chapterBeforeTocMatch = markdown.match(/\[metadata:beforeToc\]:- "([^"]+)"/i);
            const chapterBeforeToc = chapterBeforeTocMatch
                ? chapterBeforeTocMatch[1].trim() === 'true'
                : undefined;
            // Generate the HTML content from markdown.
            const html = await marked.parse(markdown);
            // Concatenate the chapter to the chapters list.
            chapters.push({
                title: chapterTitle,
                author: chapterAuthor,
                data: html,
                excludeFromToc: chapterExcludeFromToc,
                beforeToc: chapterBeforeToc,
            });
            console.log('Generated chapter from markdown file:', markdownFileName);
        }
    }
    const option = {
        title,
        description: '',
        author,
        publisher,
        cover,
        version,
        lang,
        tocTitle,
        hideToC,
        verbose: true,
        content: chapters,
    };
    try {
        const epub = new EPub(option, `${gitHubWorkspaceDir}/${output}`);
        await epub.render();
        console.log('Ebook Generated Successfully! Output:', output);
    }
    catch (error) {
        console.error('Failed to generate Ebook because of:', error);
    }
};

