        version: lib_core.getInput('version', { required: false }),
        lang: lib_core.getInput('lang', { required: false }),
        tocTitle: lib_core.getInput('tocTitle', { required: false }),
        hideToC: lib_core.getInput('hideToC', { required: false }),
